encodings = np.array(encodings)
# create a confusion matrix based on cosine similarity from each of the 12 encodings
confusion_matrix = np.zeros((12, 12))
for i in range(12):
    for j in range(12):
        cos_sim = cosine_similarity(encodings[i, :].reshape(1, -1), encodings[j, :].reshape(1, -1))
        confusion_matrix[i, j] = cos_sim

# names = ["net", "seaweed", "pipe", "towfish", "net", "tire", "tire", "hand net", "towfish", "tire", "seaweed", "net"]
names = ["net", "seaweed", "towfish", "pipe", "net", "tire", "tire", "hand net", "towfish", "tire", "seaweed", "net"]


# create another confusion matrix based on the euclidean distance from each of the 12 encodings
confusion_matrix_euclidean = np.zeros((12, 12))
for i in range(12):
    for j in range(12):
        if i != j:
            euclidean_dist = 1 / euclidean_distances(encodings[i, :].reshape(1, -1), encodings[j, :].reshape(1, -1))
            confusion_matrix_euclidean[i, j] = euclidean_dist
        else:
            confusion_matrix_euclidean[i, j] = 1
